// INA226 at 0x40 with a 2 mOhm shunt, scaled for up to 32.768 A (1 mA per count)
const ADDR = 0x40, RSHUNT = 0.002, currentLsb = 0.001;
log('Manufacturer ID =', hex(i2c.readReg16(ADDR, 0xFE)), ' Die ID =', hex(i2c.readReg16(ADDR, 0xFF)));

const cal = Math.trunc(0.00512 / (currentLsb * RSHUNT));
i2c.writeReg16(ADDR, 0x05, cal);
log('Calibration =', cal, '(' + hex(cal) + ')');

const vshunt = toInt16(i2c.readReg16(ADDR, 0x01)) * 2.5e-6;
const vbus = i2c.readReg16(ADDR, 0x02) * 1.25e-3;
const amps = toInt16(i2c.readReg16(ADDR, 0x04)) * currentLsb;
const watts = i2c.readReg16(ADDR, 0x03) * 25 * currentLsb;
log('shunt', (vshunt * 1000).toFixed(3), 'mV | bus', vbus.toFixed(3), 'V');
log('current', amps.toFixed(3), 'A | power', watts.toFixed(2), 'W');
